def get_shape(val: Any) ->Optional[List[int]]:
    if hasattr(val, 'type') and callable(val.type):
        val_type = val.type()
        if hasattr(val_type, 'sizes') and callable(val_type.sizes):
            return list(val_type.sizes())
    return None

def elementwise_flop_counter(input_scale: float=1, output_scale: float=0
    ) ->Handle:
    def _elementwise_flop(inputs: List[Any], outputs: List[Any]) ->Number:
        ret = 0
        if input_scale != 0:
            shape = get_shape(inputs[0])
            if shape is not None:
                ret += input_scale * prod(shape)
        if output_scale != 0:
            shape = get_shape(outputs[0])
            if shape is not None:
                ret += output_scale * prod(shape)
        return ret
    return _elementwise_flop

def elementwise_flop(inputs: List[Any], outputs: List[Any]) ->Number:
